def stripes(I):
    # collect nonzero cells, find slope: do all nonzero cells lie on slope +1 or -1 diagonals? return stripes grouped by coord
    cells=[(r,c,I[r][c]) for r in range(len(I)) for c in range(len(I[0])) if I[r][c]]
    for sgn in (1,-1):
        g={}
        for r,c,v in cells: g.setdefault(sgn*(r-c),set()).add(v)
        # stripes "valid" if each diagonal of this direction containing nonzero cells is uniform
        if all(len(s)==1 for s in g.values()):
            yield sgn,{k:list(s)[0] for k in g}

def solve(I):
    for sgn,sp in stripes(I):
        ks=sorted(sp); cols=sorted(set(sp.values()))
        # minimal period p such that different-colored stripes have distinct slots
        for p in range(1,50):
            slot={}
            okk=True
            for k,v in sp.items():
                s=k%p
                if s in slot and slot[s]!=v: okk=False;break
                slot[s]=v
            if okk: break
        missing=[s for s in range(p) if s not in slot]
        # fill missing slots with ascending new colors (smallest positive not in input), slot order
        unused=[x for x in range(1,10) if x not in cols]
        for i,s in enumerate(missing): slot[s]=unused[i]
        B=[slot[s] for s in range(p)]
        H,W=len(I),len(I[0])
        return [[B[sgn*((c-r))%p] for c in range(W)] for r in range(H)]

